First, we need a function to check if a number is prime. Then we will generate two-digit prime numbers and check the condition.
```python
def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def reverse_number(n):
    return int(str(n)[::-1])

def smallest_non_emirp():
    for num in range(10, 100):
        if is_prime(num):
            if not is_prime(reverse_number(num)):
                return num
    return None

smallest_non_emirp_number = smallest_non_emirp()
print(smallest_non_emirp_number)
